The query evaluator can call ``call_function(name, args, current=...)`` for
ordinary function calls.  Chained calls pass the selected value as current.
"""

class FunctionError(ValueError):
    pass


def call_function(name, args, current=None):
    """Evaluate a built-in function over already evaluated arguments."""
    if name in ("keys", "values"):
        if args:
            raise FunctionError(f'func "{name}" expects exactly 0 arguments, got {len(args)}')
        if current is None:
            raise FunctionError(f'func "{name}" expects a value')
        if isinstance(current, dict):
            return list(current.keys() if name == "keys" else current.values())
        if isinstance(current, (list, tuple)) and name == "keys":
            return list(range(len(current)))
        raise FunctionError(f'{name} can only be used on maps, got {type_name(current)}')
    if current is not None:
        args = [current] + list(args)
    if len(args) != 1:
        raise FunctionError(f'func "{name}" expects exactly 1 arguments, got {len(args)}')
    value = args[0]
    if name == "len":
        try:
            return len(value)
        except TypeError:
            raise FunctionError(f'error getting slice length: unexpected type: expected array, got {type_name(value)}')
    if name == "reverse":
        if isinstance(value, str):
            return value[::-1]
        if isinstance(value, (list, tuple)):
            return list(reversed(value))
        raise FunctionError(f'reverse expects an array or string, got {type_name(value)}')
    if name == "unique":
        if not isinstance(value, list):
            raise FunctionError(f'unique expects an array, got {type_name(value)}')
        result = []
        for item in value:
            if not any(item == prev and type(item) is type(prev) for prev in result):
                result.append(item)
        return result
    if name in ("first", "last"):
        if not isinstance(value, list):
            raise FunctionError(f'{name} expects an array, got {type_name(value)}')
        if not value:
            return None
        return value[0] if name == "first" else value[-1]
    if name == "contains":
        if not isinstance(value, list):
            raise FunctionError(f'error getting slice length: unexpected type: expected array, got {type_name(value)}')
        # The single argument itself is the array in normal function form;
        # containment is also used as a chained method with one argument.
        return False
    if name in ("toString", "toInt", "toFloat", "toBool"):
        if name == "toString":
            if isinstance(value, (dict, list)):
                raise FunctionError(f'cannot convert {type_name(value)} to string')
            return "" if value is None else str(value).lower() if isinstance(value, bool) else str(value)
        if name == "toInt":
            return int(value)
        if name == "toFloat":
            return float(value)
        if isinstance(value, bool):
            return value
        if isinstance(value, str):
            return value.lower() == "true"
        return bool(value)
    if name == "sum":
        if not isinstance(value, list):
            raise FunctionError(f'cannot sum non-numeric value of type {type_name(value)}')
        total = 0
        for item in value:
            if isinstance(item, bool) or not isinstance(item, (int, float)):
                raise FunctionError(f'cannot sum non-numeric value of type {type_name(item)}')
            total += item
        return total
    raise FunctionError(f'unknown function: "{name}"')


def type_name(value):
    if value is None:
        return "nil"
    if isinstance(value, bool):
        return "bool"
    if isinstance(value, dict):
        return "map"
    if isinstance(value, list):
        return "array"
    if isinstance(value, str):
        return "string"
    if isinstance(value, int):
        return "int"
    if isinstance(value, float):
        return "float"
    return type(value).__name__
"""Helpers for Dasel recursive descent and search selectors.

These operate on ordinary Python JSON-like values and are kept separate from
the query parser so the CLI implementation can use them directly.
"""

def _children(value):
    if isinstance(value, dict):
        return value.values()
    if isinstance(value, list):
        return value
    return ()


def recursive_values(root, key):
    """Return values at key in descendant objects, in depth-first order.

    The root object's own keys are not considered by the reference `..key`
    selector; its children are searched.
    """
    out = []
    def walk(value):
        if isinstance(value, dict):
            for k, v in value.items():
                if k == key:
                    out.append(v)
                walk(v)
        elif isinstance(value, list):
            for v in value:
                walk(v)
    for child in _children(root):
        walk(child)
    return out


def search_objects(root, key, operator, expected):
    """Find descendant objects whose direct property satisfies a comparison."""
    def matches(value):
        if key not in value:
            return False
        actual = value[key]
        try:
            # Go's JSON-backed value comparisons keep booleans distinct from
            # numbers (Python's bool is an int subclass).
            if operator in ('==', '!='):
                equal = _json_equal(actual, expected)
                return equal if operator == '==' else not equal
            return {
                '>': lambda: actual > expected,
                '<': lambda: actual < expected,
                '>=': lambda: actual >= expected,
                '<=': lambda: actual <= expected,
            }[operator]()
        except (KeyError, TypeError):
            return False

    out = []
    def walk(value):
        if isinstance(value, dict):
            if matches(value):
                out.append(value)
            for child in value.values():
                walk(child)
        elif isinstance(value, list):
            for child in value:
                walk(child)
    # As with recursive descent, the top level itself isn't a candidate.
    for child in _children(root):
        walk(child)
    return out


def _json_equal(left, right):
    if isinstance(left, bool) or isinstance(right, bool):
        return type(left) is type(right) and left == right
    if isinstance(left, dict) and isinstance(right, dict):
        return left.keys() == right.keys() and all(_json_equal(left[k], right[k]) for k in left)
    if isinstance(left, list) and isinstance(right, list):
        return len(left) == len(right) and all(_json_equal(a, b) for a, b in zip(left, right))
    if isinstance(left, (int, float)) and isinstance(right, (int, float)):
        return left == right
    return type(left) is type(right) and left == right
