def format_out(v,compact=False):
    return json_dumps(v,compact)

def function_arg(data, text):
    try:
        return json.loads(text)
    except (ValueError, TypeError):
        return select(data,parse_selector(text))

def split_call_args(text):
    parts=[]; start=0; depth=0; quote=None; escaped=False
    for i,ch in enumerate(text):
        if quote:
            if escaped: escaped=False
            elif ch=='\\': escaped=True
            elif ch==quote: quote=None
        elif ch in ('"', "'"): quote=ch
        elif ch in '([': depth+=1
        elif ch in ')]': depth-=1
        elif ch==',' and depth==0:
            parts.append(text[start:i].strip()); start=i+1
    last=text[start:].strip()
    if last or parts: parts.append(last)
    return parts

def eval_object_query(data, query):
    match=re.fullmatch(r'(.*?)(?:\.)?\{(.*)\}',query.strip())
    if not match: return None,False
    base,body=match.groups()
    context=data if not base else select(data,parse_selector(base))
    result={}
    for part in split_call_args(body):
        if not part: continue
        key,value=part.split(':',1) if ':' in part else (part,None)
        key=key.strip().strip('"\'')
        if value is None:
            if not isinstance(context,dict):
                kind='array' if isinstance(context,list) else 'nil' if context is None else 'bool' if isinstance(context,bool) else 'string' if isinstance(context,str) else 'int' if isinstance(context,int) else 'float' if isinstance(context,float) else 'map'
                raise ValueError(f'object expression error: unexpected type: expected map, got {kind}')
            if key not in context:
                raise ValueError(f'object expression error: map key not found: "{key}"')
            result[key]=context[key]
            continue
        value=value.strip()
        try: parsed=json.loads(value)
        except Exception:
            if len(value)>=2 and value[0]=="'" and value[-1]=="'": parsed=value[1:-1]
            else: parsed=select(context,parse_selector(value))
        result[key]=parsed
    return result,True

def resolve_call_arg(text, data):
    text=text.strip()
    try: return json.loads(text)
    except Exception: return select(data,parse_selector(text))

def eval_variables(expr, variables):
    pattern=r'\$([A-Za-z_][A-Za-z0-9_]*)((?:\.[A-Za-z_][A-Za-z0-9_]*|\[\d+\])*)'
    def repl(m):
        code="variables["+repr(m.group(1))+"]"
        suffix=m.group(2) or ''
        for part in re.finditer(r'\.([A-Za-z_][A-Za-z0-9_]*)|\[(\d+)\]',suffix):
            code+="["+repr(part.group(1) if part.group(1) is not None else int(part.group(2)))+"]"
        return code
    code=re.sub(pattern,repl,expr)
    code=re.sub(r'\btrue\b','True',code,flags=re.I)
    code=re.sub(r'\bfalse\b','False',code,flags=re.I)
    code=re.sub(r'\bnull\b','None',code,flags=re.I)
    return eval(code,{'__builtins__':{}},{'variables':variables})

